import fs from 'node:fs/promises';
import {pathToFileURL} from 'node:url';
export const boards=[{id:1,tag:'공지사항'},{id:14,tag:'업데이트'},{id:19,tag:'개발자 노트'},{id:7,tag:'진행 중인 이벤트'},{id:8,tag:'종료 이벤트'}];
const day=86400000;
export function normalizePost(post,now){if(!post||typeof post!=='object')return null;const board=boards.find(b=>b.id===post.boardId),date=post.publish?.publishAt||post.createdAt,time=Date.parse(date);if(!board||post.isWithdrawn||post.isAdminWritten!==true||post.publish?.publishStatus!=='Published'||!Number.isFinite(time)||time<now-14*day||time>now||typeof post.title!=='string'||!post.title.trim()||!/^([a-f\d]{8}-){1}[a-f\d]{4}-[a-f\d]{4}-[a-f\d]{4}-[a-f\d]{12}$/i.test(post.publicId||''))return null;return {id:post.publicId,title:post.title.trim(),tag:board.tag,publishedAt:new Date(time).toISOString(),url:'https://zeus.com2us.com/p/'+post.publicId};}
async function request(url,fetcher){let error;for(let attempt=0;attempt<3;attempt++){try{const response=await fetcher(url,{headers:{Accept:'application/json','User-Agent':'GuildOfficialNews/1.0 (https://zeusjj.github.io/)'},signal:AbortSignal.timeout(20000)});if(!response.ok)throw new Error('Official site HTTP '+response.status);const data=await response.json();if(!Array.isArray(data?.data?.items))throw new Error('Official site response changed');return data.data.items;}catch(e){error=e;if(attempt<2)await new Promise(resolve=>setTimeout(resolve,1000*(attempt+1)));}}throw error;}
export async function collect({now=Date.now(),fetcher=fetch}={}){const records=new Map();for(const board of boards){let previous='';for(let page=1;page<=20;page++){const url=new URL('https://zeus.com2us.com/api/posts');for(const [key,value] of Object.entries({boardId:board.id,page,pageSize:50,limit:50,sortBy:'latest'}))url.searchParams.set(key,value);const items=await request(url,fetcher),regular=items.filter(p=>p.boardId===board.id&&!p.isPinned),fingerprint=regular.map(p=>p.publicId).join(',');for(const p of items){const post=normalizePost(p,now);if(post)records.set(post.id,post);}if(!regular.length||fingerprint===previous||regular.length<50||regular.some(p=>Date.parse(p.publish?.publishAt||p.createdAt)<now-14*day))break;if(page===20)throw new Error('Official news pagination exceeded safety limit');previous=fingerprint;await new Promise(resolve=>setTimeout(resolve,300));}}
 return {collectedAt:new Date(now).toISOString(),days:14,items:[...records.values()].sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt)||a.id.localeCompare(b.id))};}
if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){const output=process.argv[2]||'official-news.json',result=await collect();const temporary=output+'.tmp';await fs.writeFile(temporary,JSON.stringify(result,null,2)+'\n');await fs.rename(temporary,output);console.log(`Collected ${result.items.length} official posts from five boards, last 14 days.`);}
